styles:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body { font-family: 'Inter', sans-serif; background: #fff; color: #1c1917; overflow-x: hidden; line-height: 1.6; }
img { max-width: 100%; display: block; }
a { text-decoration: none; }
#scroll-progress { position: fixed; top: 0; left: 0; width: 0%; height: 3px; background: linear-gradient(to right, #fbbf24, #78716c, #34d399); z-index: 9999; transition: width 0.1s linear; }
header { position: fixed; top: 3px; left: 0; right: 0; z-index: 1000; transition: all 0.5s ease; background: #262626; }
header.scrolled { background: rgba(255,255,255,0.97); backdrop-filter: blur(20px); box-shadow: 0 4px 32px rgba(0,0,0,0.12); border-bottom: 1px solid rgba(214,211,209,0.5); }
.header-inner { max-width: 1280px; margin: 0 auto; padding: 1rem 1.5rem; display: flex; align-items: center; justify-content: space-between; }
.logo { display: flex; align-items: center; gap: 0.75rem; cursor: pointer; text-decoration: none; }
.logo-icon { padding: 0.625rem; border-radius: 1rem; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); transition: all 0.3s; }
header.scrolled .logo-icon { background: linear-gradient(135deg, #44403c, #1e293b); border: none; }
.logo-icon svg { width: 1.5rem; height: 1.5rem; }
.logo-icon svg path { transition: stroke 0.3s; }
header:not(.scrolled) .logo-icon svg path { stroke: #000; }
header.scrolled .logo-icon svg path { stroke: #fff; }
.logo-text { line-height: 1.2; }
.logo-name { font-size: 1.125rem; font-weight: 700; color: #fff; transition: color 0.3s; }
header.scrolled .logo-name { color: #1c1917; }
.logo-sub { font-size: 0.7rem; font-weight: 500; color: #d6d3d1; transition: color 0.3s; }
header.scrolled .logo-sub { color: #78716c; }
nav { display: flex; align-items: center; gap: 2rem; }
nav a { font-weight: 600; font-size: 0.925rem; color: #fff; transition: color 0.3s; position: relative; }
header.scrolled nav a { color: #44403c; }
nav a::after { content: ''; position: absolute; bottom: -2px; left: 0; width: 0; height: 2px; background: #1c1917; transition: width 0.3s; }
header.scrolled nav a::after { background: #1c1917; }
header:not(.scrolled) nav a::after { background: #fff; }
nav a:hover::after { width: 100%; }
.nav-cta { display: flex; align-items: center; gap: 0.4rem; padding: 0.625rem 1.25rem; background: linear-gradient(135deg, #22c55e, #10b981); color: #fff !important; border-radius: 1rem; font-weight: 600; font-size: 0.875rem; transition: all 0.3s; box-shadow: 0 4px 16px rgba(34,197,94,0.3); }
.nav-cta:hover { background: linear-gradient(135deg, #16a34a, #059669); transform: translateY(-2px); }
.nav-cta::after { display: none !important; }
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 0.5rem; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); border-radius: 0.75rem; }
header.scrolled .hamburger { background: #f5f5f4; border-color: transparent; }
