.mobile-nav a:hover { background: rgba(255,255,255,0.1); padding-left: 1.5rem; }
.mobile-cta-wrap { margin-top: 0.75rem; }
.mobile-cta { display: flex; align-items: center; justify-content: center; gap: 0.5rem; padding: 1rem; background: linear-gradient(135deg, #22c55e, #10b981); color: #fff !important; border-radius: 1rem; font-weight: 600; }
