.product-image-box { background: linear-gradient(135deg, #1c1917, #1e293b); border: 1px solid #f5f5f4; border-radius: 1rem; height: 11rem; display: flex; align-items: center; justify-content: center; overflow: hidden; padding: 0; color: #fbbf24; font-weight: 900; font-size: 2.5rem; }
