.cta-box { margin: 3rem 0; padding: 2rem; background: linear-gradient(135deg, #1c1917 0%, #1e293b 50%, #1c1917 100%); border-radius: 1.5rem; text-align: center; color: #fff; }
.cta-hidden { display: none; }
.cta-box h3 { font-size: 1.5rem; font-weight: 700; margin-bottom: 0.75rem; }
.cta-box p { color: #d6d3d1; margin-bottom: 1.5rem; }
.cta-buttons { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; }
