.related { margin-top: 4rem; }
.related h3 { font-size: 1.5rem; font-weight: 700; color: #1c1917; margin-bottom: 2rem; }
.related-grid { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
@media (min-width: 768px) { .related-grid { grid-template-columns: repeat(3, 1fr); } }
.related-card { background: #fafaf9; border-radius: 1rem; overflow: hidden; cursor: pointer; transition: box-shadow 0.3s; }
.related-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.12); }
