.related-card-body { padding: 1rem; }
.related-card h4 { font-weight: 700; color: #1c1917; font-size: 0.875rem; margin-bottom: 0.25rem; display: -webkit-box; -webkit-line-clamp: 2; line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.related-card span { font-size: 0.75rem; color: #78716c; }
